"""Data adapters: JSON → markdown table, state literal → plain-English status."""

from __future__ import annotations

import json
from pathlib import Path

from harness.site.discovery import FeatureState


def compute_status_signal(fs: FeatureState) -> tuple[str, str]:
    """Map feature state to (emoji, plain-english label) for non-tech readers.

    Returns one of:
      ✅ Shipped
      🚫 Blocked on security
      🟢 Implementation complete, awaiting review
      🟢 Ready to implement
      🟡 Planning
      🟡 Research complete, drafting requirements
      🟡 In research
      ⚪ Draft
      ⚪ Unknown
    """
    r = fs.raw
    if r.get("review") == "PASS" and r.get("security") == "PASS":
        return ("✅", "Shipped")
    if r.get("security") == "BLOCKED":
        return ("🚫", "Blocked on security")
    if (
        r.get("gate") == "APPROVE"
        and r.get("plan_validation") == "PASS"
        and r.get("impl") == "complete"
    ):
        return ("🟢", "Implementation complete, awaiting review")
    if r.get("gate") == "APPROVE" and r.get("plan") == "complete":
        return ("🟢", "Ready to implement")
    if r.get("gate") == "APPROVE" and r.get("plan") != "complete":
        return ("🟡", "Planning")
    if r.get("research_verdict") in ("GO", "GO-WITH-CONDITIONS") and r.get("prd") != "complete":
        return ("🟡", "Research complete, drafting requirements")
    if r.get("story") == "validated" and r.get("research") != "complete":
        return ("🟡", "In research")
    if r.get("story") in ("draft", None):
        return ("⚪", "Draft")
    return ("⚪", "Unknown")


def render_testcases_md(json_path: Path) -> str:
    """Render `docs/test-cases/<id>.json` as a non-tech-readable markdown table."""
    try:
        data = json.loads(json_path.read_text(encoding="utf-8"))
    except (json.JSONDecodeError, OSError):
        return "_Test cases unavailable._\n"

    tcs = data if isinstance(data, list) else data.get("test_cases", [])
    if not tcs:
        return "_No test cases defined._\n"

    # Group by priority
    groups: dict[str, list[dict]] = {"Must": [], "Should": [], "Could": [], "Other": []}
    for tc in tcs:
        prio = tc.get("priority", "Other")
        groups.setdefault(prio, []).append(tc) if prio in groups else groups["Other"].append(tc)

    out: list[str] = []
    for prio in ("Must", "Should", "Could", "Other"):
        items = groups.get(prio, [])
        if not items:
            continue
        out.append(f"## {prio} ({len(items)})\n")
        out.append("| ID | Title | Type | Auto | Given / When / Then |")
        out.append("|---|---|---|---|---|")
        for tc in items:
            tid = tc.get("id") or tc.get("tc_id", "?")
            title = _md_escape(tc.get("title", ""))
            ttype = tc.get("type", "?")
            auto = "✓" if tc.get("automatable") else "manual"
            gwt = _format_gwt(tc)
            out.append(f"| `{tid}` | {title} | {ttype} | {auto} | {gwt} |")
        out.append("")
    return "\n".join(out)


def _format_gwt(tc: dict) -> str:
    parts = []
    for key, label in (("given", "G"), ("when", "W"), ("then", "T")):
        v = tc.get(key)
        if v:
            parts.append(f"**{label}:** {_md_escape(v)}")
    return "<br>".join(parts)


def _md_escape(text: str) -> str:
    """Escape pipe and HTML so a TC entry survives inside a markdown table cell."""
    if not isinstance(text, str):
        text = str(text)
    return text.replace("|", "\\|").replace("\n", " ")


def render_decisions_md(decisions: list[dict] | None) -> str:
    """Render `state[id].decisions[]` (written by `/decide`) as a readable markdown page.

    Empty/None input → a friendly empty-state message. Real entries are grouped by
    `blast_radius` so reviewers can scan high-impact ones first.
    """
    if not decisions:
        return "_No decisions recorded for this feature yet._\n"

    # Group by blast radius (data > system > service > feature)
    priority = {"data": 0, "system": 1, "service": 2, "feature": 3}
    groups: dict[str, list[dict]] = {}
    for d in decisions:
        br = d.get("blast_radius", "feature")
        groups.setdefault(br, []).append(d)

    out: list[str] = ["_Structured record of every non-trivial choice made while planning or building this feature. Mirrors the mini-ADRs in PLAN.md §1._\n"]
    for br in sorted(groups.keys(), key=lambda k: priority.get(k, 99)):
        entries = groups[br]
        out.append(f"## Blast radius: {br} ({len(entries)})\n")
        for d in entries:
            did = d.get("decision_id", "D-??")
            title = _md_escape(d.get("title", ""))
            chosen = _md_escape(d.get("chosen", "—"))
            alternatives = ", ".join(_md_escape(a) for a in d.get("alternatives", []) or []) or "—"
            rationale = _md_escape(d.get("rationale", ""))
            reversibility = d.get("reversibility", "—")
            adr_ref = d.get("adr_ref")
            created_at = d.get("created_at", "—")
            created_by = d.get("created_by", "—")
            out.append(f"### {did} · {title}\n")
            out.append(f"- **Chosen:** `{chosen}`")
            out.append(f"- **Alternatives:** {alternatives}")
            out.append(f"- **Reversibility:** {reversibility}")
            if adr_ref:
                out.append(f"- **ADR:** {adr_ref}")
            out.append(f"- **Recorded:** {created_at} · by `{created_by}`")
            if rationale:
                out.append(f"\n> {rationale}\n")
            else:
                out.append("")
    return "\n".join(out) + "\n"


def render_clarifications_md(clarifications: list[dict] | None) -> str:
    """Render `state[id].clarifications[]` (written by `/arh-clarify`) as a readable markdown page.

    Each round becomes a section with its questions. Status is surfaced prominently so
    the reader can see at a glance which rounds are still waiting on the PO.
    """
    if not clarifications:
        return "_No clarification rounds for this feature._\n"

    out: list[str] = ["_Mid-stream questions to the Product Owner, bundled into rounds by `/arh-clarify`. Answers flow back into the source docs via `/arh-clarify --apply`._\n"]
    for rnd in clarifications:
        round_no = rnd.get("round", "?")
        status = rnd.get("status", "—")
        asked_at = rnd.get("asked_at", "—")
        asked_by = rnd.get("asked_by", "—")
        tracker_comment = rnd.get("tracker_comment") or "—"
        status_emoji = {"asked": "⏳", "partially-answered": "🟡", "resolved": "✅"}.get(status, "•")
        out.append(f"## Round {round_no} · {status_emoji} {status}\n")
        out.append(f"- **Asked at:** {asked_at}")
        out.append(f"- **Triggered by:** `{asked_by}`")
        out.append(f"- **Tracker comment:** {tracker_comment}")
        out.append("")
        questions = rnd.get("questions") or []
        if not questions:
            out.append("_No questions recorded for this round._\n")
            continue
        # Group by category
        cats: dict[str, list[dict]] = {}
        for q in questions:
            cats.setdefault(q.get("category", "ux"), []).append(q)
        for cat in ("security", "scope", "integration", "ux"):
            items = cats.get(cat, [])
            if not items:
                continue
            out.append(f"### {cat.capitalize()} ({len(items)})\n")
            for q in items:
                qid = q.get("qid", "Q-??")
                marker = _md_escape(q.get("marker", ""))
                source_doc = q.get("source_doc", "—")
                source_line = q.get("source_line", "—")
                blocking = q.get("blocking") or "—"
                answer = q.get("answer")
                out.append(f"**{qid}** — {marker}")
                out.append(f"- Source: `{source_doc}:{source_line}` · blocks: `{blocking}`")
                if answer:
                    out.append(f"- **Answer:** {_md_escape(answer)}")
                    if q.get("answered_at"):
                        out.append(f"- Answered: {q['answered_at']}")
                else:
                    out.append("- _Awaiting answer._")
                out.append("")
    return "\n".join(out) + "\n"


def render_agent_flags_md(flags: list[dict] | None) -> str:
    """Render `state[id].agent_flags[]` (written by `/arh-human-review`) as a readable markdown page.

    Open flags appear first (commit-PR is gated on them). Triaged flags follow with verdicts
    and decision rationale — the audit trail PR reviewers need.
    """
    if not flags:
        return "_No agent flags raised for this feature._\n"

    open_flags = [f for f in flags if f.get("status") == "open"]
    triaged = [f for f in flags if f.get("status") in ("accept", "reject", "defer")]

    out: list[str] = ["_Observations the agent surfaced during implementation. Triaged by the engineer via `/arh-human-review` — commit-PR is blocked while any flag is `open`._\n"]

    if open_flags:
        out.append(f"## ⚠️ Open — {len(open_flags)} flag(s) blocking commit-PR\n")
        for f in open_flags:
            out.append(_format_flag(f, show_decision=False))
            out.append("")
    else:
        out.append("## ✅ Open — none\n")
        out.append("All raised flags have been triaged. Commit-PR is not blocked by `/arh-human-review`.\n")

    if triaged:
        out.append(f"## Triaged — {len(triaged)} flag(s)\n")
        for f in triaged:
            out.append(_format_flag(f, show_decision=True))
            out.append("")
    return "\n".join(out) + "\n"


def _format_flag(f: dict, *, show_decision: bool) -> str:
    """Format one flag as a markdown bullet block."""
    fid = f.get("flag_id", "AF-??")
    kind = f.get("kind", "other")
    summary = _md_escape(f.get("summary", ""))
    source = f.get("source", "—")
    task_id = f.get("task_id") or "—"
    raised_at = f.get("raised_at", "—")
    raised_by = f.get("raised_by", "—")
    status = f.get("status", "—")
    status_emoji = {"open": "🔴", "accept": "✅", "reject": "⚪", "defer": "🕒"}.get(status, "•")
    # Explicit attr-list anchor so cross-links from evidence.md / decisions.md /
    # clarifications.md resolve to a stable id regardless of heading text changes.
    # MkDocs Material has `attr_list` enabled via mkdocs.yml.j2 markdown_extensions.
    parts = [f"### {fid} · {status_emoji} `{kind}` · {summary} {{#{fid}}}\n"]
    parts.append(f"- **Source:** `{source}` · task: `{task_id}`")
    parts.append(f"- **Raised:** {raised_at} · by `{raised_by}`")
    if show_decision:
        verdict = status
        decision = _md_escape(f.get("decision") or "—")
        decided_by = f.get("decided_by") or "—"
        decided_at = f.get("decided_at") or "—"
        rationale = _md_escape(f.get("rationale") or "")
        parts.append(f"- **Verdict:** {verdict} · by `{decided_by}` at {decided_at}")
        parts.append(f"- **Decision:** {decision}")
        if rationale:
            parts.append(f"\n> {rationale}")
        if f.get("carry_forward_ref"):
            parts.append(f"- **Carry-forward ref:** `{f['carry_forward_ref']}`")
    return "\n".join(parts)


def render_impl_evidence_md(
    impl_evidence: dict | None,
    *,
    log_tails: dict[str, str] | None = None,
    log_links: dict[str, str] | None = None,
    available_flag_ids: set[str] | None = None,
) -> str:
    """Render `state[id].impl_evidence` (written by the implementation-agent's
    `evidence-pass` skill at end of `/arh-implement` Step 1) as a readable markdown page.

    Empty/None input → a friendly empty-state message. Real entries produce a
    summary table + per-dimension table + an inline `<details>` block embedding
    the last N lines of the evidence log for any FAILing dimension (so engineers
    can triage from the browser without SSH-ing into the repo).

    Args:
        impl_evidence: the dict from `state[id].impl_evidence`. None or missing
            `checks` → empty-state message.
        log_tails: optional map `dim_name → tail_string`. The builder reads each
            FAIL dimension's `evidence_path` and passes its tail (last N lines)
            here. PASS dimensions get no tail (link-only).
        log_links: optional map `dim_name → relative_log_url`. The builder copies
            each existing log file into the rendered site and passes the relative
            URL here so this adapter can produce `[view](evidence/<name>.log)` links.
        available_flag_ids: optional set of flag ids that actually exist in
            `state.agent_flags[]` for this feature. Used to decide which N/A
            cells link to `flags.md#AF-NN` (id present, page emitted) and which
            render as plain text with a "pending triage" hint (id referenced by
            evidence-pass but not yet bundled into `agent_flags[]` via
            `/arh-human-review`). Pass `None` to skip this awareness (assumes all
            ids resolve — only safe for adapter-level unit tests).
    """
    if not impl_evidence or not impl_evidence.get("checks"):
        return "_No implementation-evidence packet recorded for this feature yet._\n"

    log_tails = log_tails or {}
    log_links = log_links or {}

    checks = impl_evidence.get("checks") or {}
    # Stable column order — matches the canonical dimensions list
    dim_order = ["typecheck", "unit_tests", "lint", "runtime", "compile", "design_check"]

    # Aggregate counts
    pass_count = sum(1 for d in dim_order if (checks.get(d) or {}).get("status") == "PASS")
    fail_count = sum(1 for d in dim_order if (checks.get(d) or {}).get("status") == "FAIL")
    na_count = sum(1 for d in dim_order if (checks.get(d) or {}).get("status") == "N/A")
    total = sum(1 for d in dim_order if d in checks)

    rounds = impl_evidence.get("rounds")
    session_ended_at = impl_evidence.get("session_ended_at", "—")

    out: list[str] = [
        "_Six-dimension evidence packet produced by the implementation-agent at end of "
        "`/arh-implement` Step 1, before handing back to validation. Each dimension is "
        "PASS (command exit 0, evidence log captured), FAIL (command exit ≠ 0; engineer "
        "must fix and re-run), or N/A (raises an `evidence-na` agent flag for triage)._\n"
    ]

    # ---- Summary block ----
    out.append("## Summary\n")
    out.append("| Dimensions | PASS | FAIL | N/A |")
    out.append("|---|---|---|---|")
    out.append(f"| {total} | ✅ {pass_count} | ❌ {fail_count} | ⚪ {na_count} |")
    out.append("")
    if rounds is not None:
        retries = max(0, int(rounds) - 1)
        suffix = "" if retries == 0 else f" — agent's internal fix loop required {retries} retry round(s)"
        out.append(f"- **Rounds:** {rounds}{suffix}")
    out.append(f"- **Session ended:** {session_ended_at}")
    out.append("")

    # ---- Per-dimension table ----
    out.append("## Checks\n")
    out.append("| Dimension | Status | Command | Exit | Log | Flag |")
    out.append("|---|---|---|---|---|---|")
    for dim in dim_order:
        info = checks.get(dim)
        if not info:
            continue
        status = info.get("status", "—")
        emoji = {"PASS": "✅", "FAIL": "❌", "N/A": "⚪"}.get(status, "•")
        command = info.get("command")
        cmd_cell = f"`{_md_escape(command)}`" if command else "—"
        exit_code = info.get("exit_code")
        exit_cell = str(exit_code) if exit_code is not None else "—"

        # Log cell — link if log_links provided, else show path or dash
        log_cell = "—"
        if dim in log_links:
            link = log_links[dim]
            # Runtime dimension carries an extra boot_log_scan signal worth surfacing
            if dim == "runtime":
                scan = info.get("boot_log_scan") or ""
                scan_suffix = f" — scan: {scan}" if scan else ""
                log_cell = f"[view]({link}){scan_suffix}"
            else:
                log_cell = f"[view]({link})"
        elif info.get("evidence_path"):
            log_cell = f"`{info['evidence_path']}`"

        # Flag cell — N/A dimensions carry a flag_id; cross-link to the explicit
        # attr-list anchor that `_format_flag` injects on each flag heading in
        # `flags.md`. Anchor is case-preserving (matches the flag id verbatim).
        # When the id is referenced by evidence-pass but not yet bundled to
        # `state.agent_flags[]` (the window before `/arh-human-review` runs),
        # render as plain text with a hint instead of a 404-bound link.
        flag_id = info.get("flag_id")
        if not flag_id:
            flag_cell = "—"
        elif available_flag_ids is None or flag_id in available_flag_ids:
            flag_cell = f"[{flag_id}](flags.md#{flag_id})"
        else:
            flag_cell = f"`{flag_id}` _(pending /arh-human-review)_"

        dim_display = dim.replace("_", " ").capitalize()
        out.append(f"| {dim_display} | {emoji} {status} | {cmd_cell} | {exit_cell} | {log_cell} | {flag_cell} |")

    out.append("")

    # ---- Failure details (tail-only inline for FAILs) ----
    fail_dims = [d for d in dim_order if (checks.get(d) or {}).get("status") == "FAIL"]
    if fail_dims:
        out.append("## Failure details\n")
        out.append(
            "_The last 20 lines of each failing dimension's evidence log are embedded "
            "below. Click 'view' in the table above for the full log file._\n"
        )
        for dim in fail_dims:
            dim_display = dim.replace("_", " ").capitalize()
            tail = log_tails.get(dim, "_log tail unavailable_")
            out.append(f"<details><summary>❌ {dim_display} — last 20 lines</summary>\n")
            out.append("```")
            out.append(tail)
            out.append("```")
            out.append("</details>\n")

    return "\n".join(out) + "\n"


def render_state_table(features: list[FeatureState]) -> str:
    """Markdown table summarising all features for the status board."""
    out = [
        "| Feature | Title | Status | Phase | Tracker |",
        "|---|---|---|---|---|",
    ]
    for fs in features:
        emoji, label = compute_status_signal(fs)
        title = _md_escape(fs.title)
        phase = fs.raw.get("phase", "—")
        tracker_key = fs.raw.get("tracker_key", "")
        tracker_url = fs.raw.get("tracker_url", "")
        tracker_cell = f"[{tracker_key}]({tracker_url})" if tracker_key and tracker_url else tracker_key or "—"
        out.append(
            f"| [{fs.feature_id}](features/{fs.feature_id}/index.md) | {title} | {emoji} {label} | {phase} | {tracker_cell} |"
        )
    return "\n".join(out)
